22	// ─── ITCH 5.0 message sizes (bytes, excluding the 2-byte length prefix) ─────
23	// Sizes from Nasdaq TotalView-ITCH 5.0 specification §4.
24	// Only the types we care about are listed; everything else falls through to
25	// the skip branch which reads the declared length from the frame header.
26	
27	static constexpr uint16_t SIZE_ADD_ORDER          = 36;
28	static constexpr uint16_t SIZE_ADD_ORDER_MPID     = 40;
29	static constexpr uint16_t SIZE_EXECUTE_ORDER      = 31;
30	static constexpr uint16_t SIZE_EXECUTE_ORDER_PRICE= 36;
31	static constexpr uint16_t SIZE_CANCEL_ORDER       = 23;
32	static constexpr uint16_t SIZE_DELETE_ORDER       = 19;
33	static constexpr uint16_t SIZE_REPLACE_ORDER      = 35;
34	
35	// Field offsets within each message body (after the 1-byte type field).
36	// Timestamp (6 bytes) follows the type at offset 1; fields begin at offset 7
37	// for most types.
38	
39	// Add Order (type 'A', 36 bytes)
40	//   [0]  type 1B
41	//   [1]  stock locate 2B
42	//   [3]  tracking number 2B
43	//   [5]  timestamp 6B
44	//   [11] order ref 8B
45	//   [19] side 1B
46	//   [20] shares 4B
47	//   [24] stock 8B
48	//   [32] price 4B
49	static constexpr int OFF_A_REF    = 11;
50	static constexpr int OFF_A_SIDE   = 19;
51	static constexpr int OFF_A_SHARES = 20;
52	static constexpr int OFF_A_PRICE  = 32;
53	
54	// Execute Order (type 'E', 31 bytes)
55	//   [0]  type 1B, [1] stock locate 2B, [3] tracking 2B, [5] ts 6B
56	//   [11] order ref 8B
57	//   [19] executed shares 4B
58	//   [23] match number 8B
59	static constexpr int OFF_E_REF    = 11;
60	static constexpr int OFF_E_SHARES = 19;
61	
62	// Delete Order (type 'D', 19 bytes)
63	//   [11] order ref 8B
64	static constexpr int OFF_D_REF = 11;
65	
66	// Replace Order (type 'U', 35 bytes)
67	//   [11] original order ref 8B
68	//   [19] new order ref 8B
69	//   [27] shares 4B
70	//   [31] price 4B
71	static constexpr int OFF_U_OLD_REF = 11;
72	static constexpr int OFF_U_NEW_REF = 19;
73	static constexpr int OFF_U_SHARES  = 27;
74	static constexpr int OFF_U_PRICE   = 31;
75	
76	// ─── Parser implementation ───────────────────────────────────────────────────
77	
78	ParseStats parse_buffer(
79	        const uint8_t* buf,
80	        std::size_t    len,
81	        MessageVisitor visitor) {
82	
83	    ParseStats stats;
84	    std::size_t pos = 0;
85	
86	    while (pos + 2 <= len) {
87	        const uint16_t msg_len = be16(buf + pos);
88	        pos += 2;
89	
90	        if (msg_len == 0) {
91	            // Padding / heartbeat frame — skip without error.
92	            continue;
93	        }
94	        if (pos + msg_len > len) {
95	            // Truncated message at end of buffer — stop cleanly.
96	            ++stats.error_count;
97	            break;
98	        }
99	
100	        const uint8_t* msg = buf + pos;
101	        const MsgType  typ = static_cast<MsgType>(msg[0]);
102	
103	        switch (typ) {
104	        case MsgType::AddOrder:
105	        case MsgType::AddOrderMPID: {
106	            if (msg_len < SIZE_ADD_ORDER) { ++stats.error_count; break; }
107	            AddOrder a;
108	            a.order_ref = be64(msg + OFF_A_REF);
109	            a.side      = static_cast<char>(msg[OFF_A_SIDE]);
110	            a.shares    = be32(msg + OFF_A_SHARES);
111	            a.price     = be32(msg + OFF_A_PRICE);
112	            ++stats.add_count;
113	            if (visitor.on_add) visitor.on_add(a);
114	            break;
115	        }
116	        case MsgType::ExecuteOrder:
117	        case MsgType::ExecuteOrderPrice: {
118	            if (msg_len < SIZE_EXECUTE_ORDER) { ++stats.error_count; break; }
119	            ExecuteOrder e;
120	            e.order_ref      = be64(msg + OFF_E_REF);
121	            e.executed_shares = be32(msg + OFF_E_SHARES);
122	            ++stats.execute_count;
123	            if (visitor.on_execute) visitor.on_execute(e);
124	            break;
125	        }
126	        case MsgType::DeleteOrder: {
127	            if (msg_len < SIZE_DELETE_ORDER) { ++stats.error_count; break; }
128	            DeleteOrder d;
129	            d.order_ref = be64(msg + OFF_D_REF);
130	            ++stats.delete_count;
131	            if (visitor.on_delete) visitor.on_delete(d);
132	            break;
133	        }
134	        case MsgType::ReplaceOrder: {
135	            if (msg_len < SIZE_REPLACE_ORDER) { ++stats.error_count; break; }
136	            ReplaceOrder r;
137	            r.old_order_ref = be64(msg + OFF_U_OLD_REF);
138	            r.new_order_ref = be64(msg + OFF_U_NEW_REF);
139	            r.shares        = be32(msg + OFF_U_SHARES);
140	            r.price         = be32(msg + OFF_U_PRICE);
141	            ++stats.replace_count;
142	            if (visitor.on_replace) visitor.on_replace(r);
143	            break;
144	        }
145	        case MsgType::CancelOrder:
146	        default:
147	            // Known-cancel and all unrecognised types: skip silently.
148	            ++stats.skipped_count;
149	            break;
150	        }
151	
152	        pos += msg_len;
153	    }
154	
155	    return stats;
156	}
