#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

#include "volume_metrics.hpp"

namespace py = pybind11;
using namespace oil_volume;

PYBIND11_MODULE(oil_volume_cpp, m) {
    m.doc() = "C++ core for oil-volume metrics (pybind11 bridge)";

    m.def(
        "rolling_mean",
        &rolling_mean,
        py::arg("values"),
        py::arg("window"),
        "Rolling arithmetic mean over *values* with the given *window*.\n"
        "Returns a list of length len(values); the first window-1 entries are NaN."
    );

    m.def(
        "capacity_utilization",
        &capacity_utilization,
        py::arg("storage_kb"),
        py::arg("capacity_kb"),
        "Capacity utilization % = storage_kb / capacity_kb * 100.\n"
        "capacity_kb: operational capacity in thousand barrels (e.g. 76000 for Cushing)."
    );

    m.def(
        "days_of_supply",
        &days_of_supply,
        py::arg("storage_kb"),
        py::arg("production_kbd"),
        "Days of supply = storage_kb / production_kbd.\n"
        "Both vectors must be the same length. Returns NaN where production_kbd <= 0."
    );

    m.def(
        "fill_rate",
        &fill_rate,
        py::arg("storage_kb"),
        "Week-over-week change in storage (storage[i] - storage[i-1]).\n"
        "First element is NaN (no prior period)."
    );
}

"""Wrapper for the oil-volume C++ extension with a pure-Python fallback.

Importing this module never fails. If ``oil_volume_cpp`` is not built the
pure-Python implementations are used instead and ``USING_CPP`` is False.
Callers can display a "running unoptimised" notice when ``USING_CPP`` is
False.
"""

from __future__ import annotations

import math
from typing import Sequence

try:
    import oil_volume_cpp as _cpp

    USING_CPP = True
except ImportError:
    _cpp = None  # type: ignore[assignment]
    USING_CPP = False

# Cushing, OK operational storage capacity (thousand barrels, DOE figure as of 2024).
CUSHING_CAPACITY_KB: float = 76_000.0


# ─── Public API ───────────────────────────────────────────────────────────────

def capacity_utilization(storage_kb: Sequence[float], capacity_kb: float = CUSHING_CAPACITY_KB) -> list[float]:
    """Capacity utilization % = storage_kb / capacity_kb * 100."""
    if USING_CPP:
        return _cpp.capacity_utilization(list(storage_kb), capacity_kb)
    if capacity_kb <= 0:
        raise ValueError("capacity_kb must be positive")
    return [v / capacity_kb * 100.0 for v in storage_kb]


def days_of_supply(storage_kb: Sequence[float], production_kbd: Sequence[float]) -> list[float]:
    """Days of supply = storage_kb / production_kbd.

    production_kbd is in thousand barrels per day. Returns NaN where production <= 0.
    """
    if USING_CPP:
        return _cpp.days_of_supply(list(storage_kb), list(production_kbd))
    out: list[float] = []
    for s, p in zip(storage_kb, production_kbd):
        out.append(math.nan if (math.isnan(p) or p <= 0) else s / p)
    return out


def fill_rate(storage_kb: Sequence[float]) -> list[float]:
    """Week-over-week change in storage (storage[i] - storage[i-1]).

    First element is NaN (no prior period).
    """
    if USING_CPP:
        return _cpp.fill_rate(list(storage_kb))
    lst = list(storage_kb)
    if not lst:
        return []
    out = [math.nan]
    for i in range(1, len(lst)):
        out.append(lst[i] - lst[i - 1])
    return out


def rolling_mean(values: Sequence[float], window: int) -> list[float]:
    """Rolling arithmetic mean; first (window-1) entries are NaN."""
    if USING_CPP:
        return _cpp.rolling_mean(list(values), window)
    if window <= 0:
        raise ValueError("window must be positive")
    lst = list(values)
    out: list[float] = []
    for i, _ in enumerate(lst):
        if i + 1 < window:
            out.append(math.nan)
        else:
            out.append(sum(lst[i - window + 1 : i + 1]) / window)
    return out

    fig.add_scatter(x=series.index, y=series.to_numpy(), mode="lines")
    fig.update_layout(title=title, yaxis_title=yaxis, height=300, margin=dict(l=10, r=10, t=40, b=10))
    return fig


def _render_results(result) -> None:
    ll = result.leadlag
    st.subheader("Results")

    c1, c2, c3 = st.columns(3)
    leader = "CL (futures)" if ll.x_leads else ("XLE" if ll.peak_lag < 0 else "contemporaneous")
    c1.metric("Lead-lag leader", leader, f"peak lag {ll.peak_lag}")
    if result.granger:
        g = result.granger["x->y"]
        c2.metric(f"Granger {SYMBOLS[LEAD]}→{SYMBOLS[LAG]}", f"p={g.p_value:.3f}",
                  "significant" if g.significant else "n.s.")
    if result.spot_check:
        c3.metric("CL=F vs FRED spot", f"{result.spot_check['median_abs_pct']:.1f}%",
                  f"{result.spot_check['common_days']} common days")

    st.plotly_chart(_ccf_figure(ll), use_container_width=True)

    gc, cc = st.columns(2)
    with gc:
        st.markdown("**Granger causality (both directions)**")
        if result.granger:
            rows = [
                {"direction": g.direction, "best lag": g.best_lag,
                 "p-value": round(g.p_value, 4), "significant": g.significant}
                for g in result.granger.values()
            ]
            st.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True)
            st.caption("Granger = predictive precedence, not true causation (paper Part 2.3).")
    with cc:
        st.markdown("**Cointegration (price levels)**")
        if result.eg_coint:
            st.write("•", result.eg_coint.verdict)
        if result.johansen_coint:
            st.write("•", result.johansen_coint.verdict)

    rc, rb = st.columns(2)
    if result.rolling_corr is not None and not result.rolling_corr.empty:
        rc.plotly_chart(
            _line(result.rolling_corr, f"Rolling correlation ({SYMBOLS[LEAD]} vs {SYMBOLS[LAG]})", "corr"),
            use_container_width=True,
        )
    if result.rolling_beta is not None and not result.rolling_beta.empty:
        rb.plotly_chart(
            _line(result.rolling_beta, f"Rolling β of {SYMBOLS[LAG]} to oil", "beta"),
            use_container_width=True,
        )

    if result.warnings:
        for w in result.warnings:
            st.warning(w)


def _render_costs(result) -> None:
    st.subheader("Projected costs")
    a, b, c = st.tabs(["① API free-tier budget", "② Transaction cost", "③ Compute / time"])

