TEST(MicroEngine, CancelViaParserRemovesPhantomDepth) {
    // The real-data regression: order partially executed, remainder canceled
    // via 'X'. Without X handling the book keeps phantom shares forever.
    const uint64_t TS = 34'200'000'000'000ull;
    auto buf = cat({
        make_add(TS,      1, 'B', 100, BID_P),
        make_add(TS + 1,  2, 'S', 200, ASK_P),
        make_execute(TS + 2, 1, 82),          // 100 -> 18 sh remain
        make_cancel(TS + 3, 1, 18),           // remainder canceled: bid gone
    });

    itch::MicrostructureEngine eng(MIN_P, MAX_P);
    itch::ParseStats stats = itch::parse_buffer(buf.data(), buf.size(), eng.visitor());
    EXPECT_EQ(stats.cancel_count, 1u);
    EXPECT_EQ(stats.error_count,  0u);

    // Bid side must be EMPTY now — the cancel event itself is one-sided
    // (no bid left), so it is skipped and the book reports no phantom bid.
    auto tob = eng.book().top_of_book();
    EXPECT_FALSE(tob.best_bid.has_value());
    ASSERT_TRUE(tob.best_ask.has_value());
    EXPECT_EQ(eng.book().order_count(), 1u);   // only the ask order remains
}

