// Market-making sim tests. One (or more) case per acceptance criterion in
// .claude/plans/avellaneda-stoikov-mm-sim.md (steps 1-4).

#include <gtest/gtest.h>
#include "../itch/mm_simulator.hpp"
#include "../itch/order_book_flat.hpp"
#include "../itch/order_book_queue.hpp"
#include "../itch/shadow_order.hpp"

#include <cstdint>
#include <vector>

namespace {

void put_be(std::vector<uint8_t>& b, std::size_t off, uint64_t v, int n) {
    for (int i = 0; i < n; ++i)
        b[off + i] = static_cast<uint8_t>((v >> (8 * (n - 1 - i))) & 0xFF);
}

// Append a framed ITCH message: 2-byte BE length + body of body_len bytes.
// Returns the body's start offset so the caller can fill type-specific fields.
std::size_t begin_msg(std::vector<uint8_t>& buf, uint16_t body_len, char type,
                      uint64_t ts) {
    buf.push_back(static_cast<uint8_t>(body_len >> 8));
    buf.push_back(static_cast<uint8_t>(body_len & 0xFF));
    const std::size_t start = buf.size();
    buf.resize(start + body_len, 0);
    buf[start] = static_cast<uint8_t>(type);
    put_be(buf, start + 5, ts, 6);  // timestamp at offset 5
    return start;
}

void add_order(std::vector<uint8_t>& buf, uint64_t ts, uint64_t ref, char side,
               uint32_t shares, uint32_t price) {
    const std::size_t s = begin_msg(buf, 36, 'A', ts);  // SIZE_ADD_ORDER
    put_be(buf, s + 11, ref, 8);
    buf[s + 19] = static_cast<uint8_t>(side);
    put_be(buf, s + 20, shares, 4);
    put_be(buf, s + 32, price, 4);
}

void execute_order(std::vector<uint8_t>& buf, uint64_t ts, uint64_t ref,
                   uint32_t shares) {
    const std::size_t s = begin_msg(buf, 31, 'E', ts);  // SIZE_EXECUTE_ORDER
    put_be(buf, s + 11, ref, 8);
    put_be(buf, s + 19, shares, 4);
}

}  // namespace

// ── OrderBookQueue (mm-1) ────────────────────────────────────────────────────

TEST(OrderBookQueue, TopOfBookParityWithFlatBook) {
    itch::OrderBookQueue q(2'800'000, 3'000'000);
    itch::OrderBookFlat f(2'800'000, 3'000'000);

    auto both_add = [&](uint64_t r, char s, uint32_t px, uint32_t sh) {
        q.add(r, s, px, sh);
        f.add(r, s, px, sh);
    };
    both_add(1, 'B', 2'899'900, 100);
    both_add(2, 'B', 2'899'900, 200);   // same level, behind #1
    both_add(3, 'B', 2'899'800, 300);
    both_add(4, 'S', 2'900'100, 150);
    both_add(5, 'S', 2'900'200, 250);

    auto same_tob = [&]() {
        const itch::TopOfBook a = q.top_of_book();
        const itch::TopOfBook b = f.top_of_book();
        ASSERT_EQ(a.best_bid.has_value(), b.best_bid.has_value());
        ASSERT_EQ(a.best_ask.has_value(), b.best_ask.has_value());
        if (a.best_bid) {
            EXPECT_EQ(a.best_bid->price_raw, b.best_bid->price_raw);
            EXPECT_EQ(a.best_bid->shares, b.best_bid->shares);
        }
        if (a.best_ask) {
            EXPECT_EQ(a.best_ask->price_raw, b.best_ask->price_raw);
            EXPECT_EQ(a.best_ask->shares, b.best_ask->shares);
        }
    };
    same_tob();  // best bid 2,899,900 x 300 ; best ask 2,900,100 x 150

    q.execute(1, 100); f.execute(1, 100);  // consume front of best bid
    same_tob();
    q.del(4); f.del(4);                     // delete best ask
    same_tob();
    q.replace(2, 6, 200, 2'899'700); f.replace(2, 6, 200, 2'899'700);
    same_tob();
}

TEST(OrderBookQueue, LevelQueueIsFIFOByArrival) {
    itch::OrderBookQueue q(2'800'000, 3'000'000);
    q.add(10, 'B', 2'899'900, 100);
    q.add(11, 'B', 2'899'900, 200);
    q.add(12, 'B', 2'899'900, 300);

    const auto& lvl = q.level_queue('B', 2'899'900);
    ASSERT_EQ(lvl.size(), 3u);
    EXPECT_EQ(lvl[0].order_ref, 10u);   // arrival order preserved
    EXPECT_EQ(lvl[1].order_ref, 11u);
    EXPECT_EQ(lvl[2].order_ref, 12u);

    q.execute(10, 40);  // partial fill of the front order
    EXPECT_EQ(q.level_queue('B', 2'899'900)[0].shares, 60u);
    EXPECT_EQ(q.level_shares('B', 2'899'900), 60u + 200u + 300u);
    q.execute(10, 60);  // finish the front order -> it leaves the queue
    EXPECT_EQ(q.level_queue('B', 2'899'900).size(), 2u);
    EXPECT_EQ(q.level_queue('B', 2'899'900)[0].order_ref, 11u);
}

// ── ShadowOrder (mm-2) ───────────────────────────────────────────────────────

TEST(ShadowOrder, FillsOnlyAfterAheadQueueEmpties) {
    itch::ShadowOrder o('B', 2'899'900, /*size=*/100, /*ahead=*/300);
    EXPECT_EQ(o.on_execution_at_level(250), 0u);  // 300 ahead -> 50 ahead
    EXPECT_EQ(o.queue_ahead(), 50u);
    EXPECT_EQ(o.on_execution_at_level(100), 50u); // 50 clears ahead, 50 fills us
    EXPECT_TRUE(o.filled());
    EXPECT_EQ(o.remaining(), 0u);
}

TEST(ShadowOrder, CancelAheadPromotesQueuePosition) {
    itch::ShadowOrder o('B', 2'899'900, /*size=*/100, /*ahead=*/300);
    o.on_ahead_order_reduced(100);                // 300 -> 200 ahead
    EXPECT_EQ(o.queue_ahead(), 200u);
    EXPECT_EQ(o.on_execution_at_level(250), 50u); // 200 clears, 50 fills us
    EXPECT_EQ(o.on_execution_at_level(100), 50u); // remaining 50 fills us
    EXPECT_TRUE(o.filled());
}

// ── A-S quoter + latency queue (mm-3) ───────────────────────────────────────

TEST(ASQuoter, PositiveInventorySkewsReservationBelowMid) {
    itch::MMParams p;
    const double mid = 2'900'000.0;
    const double sigma2 = 100.0, trem = 1.0;

    const itch::ASQuote flat = itch::as_quote(mid, 0, sigma2, trem, p, 2'899'900, 2'900'100);
    EXPECT_DOUBLE_EQ(flat.reservation, mid);  // no inventory -> reservation at mid

    const itch::ASQuote longq = itch::as_quote(mid, 200, sigma2, trem, p, 2'899'900, 2'900'100);
    EXPECT_LT(longq.reservation, mid);        // long -> quote to sell down, r < mid

    const itch::ASQuote shortq = itch::as_quote(mid, -200, sigma2, trem, p, 2'899'900, 2'900'100);
    EXPECT_GT(shortq.reservation, mid);       // short -> r > mid (symmetric)
}

TEST(ASQuoter, InventoryCapPullsRiskIncreasingSide) {
    itch::MMParams p;
    p.inventory_cap = 500;
    const itch::ASQuote at_long_cap =
        itch::as_quote(2'900'000.0, 500, 100.0, 1.0, p, 2'899'900, 2'900'100);
    EXPECT_TRUE(at_long_cap.bid_pulled);   // stop buying when long at the cap
    EXPECT_EQ(at_long_cap.bid_raw, 0u);
    EXPECT_FALSE(at_long_cap.ask_pulled);
}

TEST(LatencyQueue, NoActionAppliesBeforeTriggerTimePlusDelay) {
    itch::LatencyActionQueue<int> q;
    q.push(1'000, 1);   // effective at t=1000
    q.push(1'000, 2);   // FIFO tie -> applies after #1
    q.push(2'000, 3);

    std::vector<int> applied;
    q.drain(999, [&](int a) { applied.push_back(a); });
    EXPECT_TRUE(applied.empty());              // nothing before t=1000

    q.drain(1'000, [&](int a) { applied.push_back(a); });
    EXPECT_EQ(applied, (std::vector<int>{1, 2}));  // both due, in FIFO order

    q.drain(1'999, [&](int a) { applied.push_back(a); });
    EXPECT_EQ(applied.size(), 2u);             // the t=2000 action still waits

    q.drain(2'000, [&](int a) { applied.push_back(a); });
    EXPECT_EQ(applied, (std::vector<int>{1, 2, 3}));
}

// ── Simulator (mm-4) ─────────────────────────────────────────────────────────

namespace {
std::vector<uint8_t> two_sided_scenario() {
    std::vector<uint8_t> buf;
    uint64_t ts = 34'200'000'000'000ULL;  // ~09:30 ET in ns
    const uint64_t step = 5'000'000ULL;   // 5 ms between events
    add_order(buf, ts += step, 1, 'B', 200, 2'899'900);
    add_order(buf, ts += step, 2, 'S', 200, 2'900'100);
    add_order(buf, ts += step, 3, 'B', 300, 2'899'800);
    add_order(buf, ts += step, 4, 'S', 300, 2'900'200);
    add_order(buf, ts += step, 5, 'B', 100, 2'899'900);
    execute_order(buf, ts += step, 1, 200);   // trade through the best bid
    execute_order(buf, ts += step, 2, 100);   // trade through the best ask
    add_order(buf, ts += step, 6, 'S', 150, 2'900'100);
    execute_order(buf, ts += step, 6, 150);
    return buf;
}
}  // namespace

TEST(MMSimulator, DeterministicPnLOnIdenticalParams) {
    const std::vector<uint8_t> buf = two_sided_scenario();
    itch::MMParams p;
    p.latency_ns = 0;  // apply requotes immediately so fills can occur

    itch::MMSimulator sim_a(p), sim_b(p);
