namespace {
std::vector<uint8_t> two_sided_scenario() {
    std::vector<uint8_t> buf;
    uint64_t ts = 34'200'000'000'000ULL;  // ~09:30 ET in ns
    const uint64_t step = 5'000'000ULL;   // 5 ms between events
    add_order(buf, ts += step, 1, 'B', 200, 2'899'900);
    add_order(buf, ts += step, 2, 'S', 200, 2'900'100);
    add_order(buf, ts += step, 3, 'B', 300, 2'899'800);
    add_order(buf, ts += step, 4, 'S', 300, 2'900'200);
    add_order(buf, ts += step, 5, 'B', 100, 2'899'900);
    execute_order(buf, ts += step, 1, 200);   // trade through the best bid
    execute_order(buf, ts += step, 2, 100);   // trade through the best ask
    add_order(buf, ts += step, 6, 'S', 150, 2'900'100);
    execute_order(buf, ts += step, 6, 150);
    return buf;
}
}  // namespace

TEST(MMSimulator, DeterministicPnLOnIdenticalParams) {
    const std::vector<uint8_t> buf = two_sided_scenario();
    itch::MMParams p;
    p.latency_ns = 0;  // apply requotes immediately so fills can occur

    itch::MMSimulator sim_a(p), sim_b(p);
    const itch::MMResult a = sim_a.run(buf.data(), buf.size());
    const itch::MMResult b = sim_b.run(buf.data(), buf.size());

    ASSERT_EQ(a.samples.size(), b.samples.size());
    for (std::size_t i = 0; i < a.samples.size(); ++i) {
        EXPECT_EQ(a.samples[i].timestamp_ns, b.samples[i].timestamp_ns);
        EXPECT_DOUBLE_EQ(a.samples[i].mark_to_mid_pnl, b.samples[i].mark_to_mid_pnl);
        EXPECT_EQ(a.samples[i].inventory, b.samples[i].inventory);
    }
    EXPECT_EQ(a.fills.size(), b.fills.size());
    EXPECT_DOUBLE_EQ(a.realized_pnl, b.realized_pnl);
    EXPECT_EQ(a.terminal_inventory, b.terminal_inventory);
    EXPECT_DOUBLE_EQ(a.terminal_mark, b.terminal_mark);
}

TEST(MMSimulator, PnLDecompositionSumsToTerminalMark) {
    const std::vector<uint8_t> buf = two_sided_scenario();
    itch::MMParams p;
    p.latency_ns = 0;
    itch::MMSimulator sim(p);
    const itch::MMResult r = sim.run(buf.data(), buf.size());

    ASSERT_FALSE(r.samples.empty());
    // realized (net cash) + terminal inventory mark == final mark-to-mid PnL.
    const double final_mark = r.samples.back().mark_to_mid_pnl;
    EXPECT_NEAR(r.realized_pnl + r.terminal_mark, final_mark, 1e-9);
}

