// Regression for the both-sides-reset bug: an ask-only reprice must NOT reset
// the resting bid shadow to full size. With tiny gamma the bid clamps to a
// fixed best_bid (no inventory-driven bid reprice), so its shadow is placed
// once; a later better-ask reprices only the ask. Total bid fills must respect
// the quote_size cap (100), not double it.
TEST(MMSimulator, QuoteSizeCapHoldsWhenOnlyOtherSideReprices) {
    std::vector<uint8_t> buf;
    uint64_t ts = 34'200'000'000'000ULL;
    const uint64_t step = 1'000'000ULL;
    add_order(buf, ts += step, 1, 'B', 100, 2'899'900);   // best bid (our ahead)
    add_order(buf, ts += step, 2, 'S', 500, 2'900'300);   // best ask -> we quote
    add_order(buf, ts += step, 3, 'B', 100, 2'899'900);   // behind our shadow
    add_order(buf, ts += step, 4, 'B', 100, 2'899'900);   // behind our shadow
    execute_order(buf, ts += step, 1, 100);               // drain ahead (ref1)
    execute_order(buf, ts += step, 3, 100);               // spills into us -> fill 100
    add_order(buf, ts += step, 5, 'S', 100, 2'900'200);   // better ask -> ASK-only reprice
    execute_order(buf, ts += step, 4, 100);               // must NOT refill a reset bid

    itch::MMParams p;
    p.latency_ns = 0;
    p.gamma = 1e-9;  // negligible inventory skew -> bid stays clamped at best_bid
    itch::MMSimulator sim(p);
    const itch::MMResult r = sim.run(buf.data(), buf.size());

    EXPECT_LE(side_filled(r, 'B'), p.quote_size);  // the bug produced 200
}

// End-to-end cancel/delete wiring: a run whose tape contains cancels and
// deletes of resting orders stays deterministic and drives the reduce_ahead
// path without error (the isolated promote math is in the ShadowOrder tests).
TEST(MMSimulator, CancelsAndDeletesRunDeterministically) {
    std::vector<uint8_t> buf;
    uint64_t ts = 34'200'000'000'000ULL;
