31	// RuntimeError) on any IO failure so callers never see a partial parse.
32	std::vector<uint8_t> read_file(const std::string& path) {
33	    std::unique_ptr<std::FILE, int (*)(std::FILE*)> f(
34	        std::fopen(path.c_str(), "rb"), &std::fclose);
35	    if (!f) throw std::runtime_error("cannot open ITCH file: " + path);
36	    if (std::fseek(f.get(), 0, SEEK_END) != 0)
37	        throw std::runtime_error("cannot seek ITCH file: " + path);
38	    const long size = std::ftell(f.get());
39	    if (size < 0) throw std::runtime_error("cannot stat ITCH file: " + path);
40	    std::rewind(f.get());
41	    std::vector<uint8_t> buf(static_cast<std::size_t>(size));
42	    if (!buf.empty() &&
43	        std::fread(buf.data(), 1, buf.size(), f.get()) != buf.size())
44	        throw std::runtime_error("short read on ITCH file: " + path);
45	    return buf;
46	}
